/* Local organizer permissions are a demo, not server-side authorization. */
let editingGroupId=null;
for(const group of demoGroups)if(!group.ownerId)group.ownerId=/^(series-|group-)/.test(group.id)?'me':'demo';
const groupHasStarted=group=>new Date(group.date+'T'+group.time).getTime()<=Date.now();
const canEditGroup=group=>group.ownerId==='me'&&!groupHasStarted(group);
const groupEditFields=['groupName','groupDate','groupTime','groupPlace','groupCapacity'];
function resetGroupEditor(){editingGroupId=null;$('#recurrenceUntil').disabled=false;for(const id of groupEditFields)$('#'+id).disabled=false;$('#groupCapacity').min=2;I18n.text($('#groupForm h1'),'Crea una serata aperta');I18n.text($('#groupForm button[type=submit]'),'Crea partita aperta');$('#groupRecurring').closest('.recurrence-box').hidden=false;$('#editGroupNotice')?.remove();}
function editGroup(group){if(!canEditGroup(group)){toast('Puoi modificare solo le tue partite non ancora iniziate.');return;}resetGroupEditor();editingGroupId=group.id;$('#recurrenceUntil').required=false;$('#recurrenceUntil').disabled=true;const values=[group.name,group.date,group.time,group.place,group.capacity];groupEditFields.forEach((id,i)=>$('#'+id).value=values[i]);$('#groupCapacity').min=Math.max(2,group.members.length);const others=group.members.some(member=>member.id!=='me');for(const id of ['groupDate','groupTime','groupPlace'])$('#'+id).disabled=others;I18n.text($('#groupForm h1'),'Modifica partita');I18n.text($('#groupForm button[type=submit]'),'Salva modifiche');$('#groupRecurring').closest('.recurrence-box').hidden=true;I18n.insert($('#groupForm h1'),'afterend','<p id="editGroupNotice" class="groups-note">'+(others?'Data, orario e palestra sono bloccati perché ci sono altri iscritti.':'Puoi aggiornare data, orario e palestra finché non ci sono altri iscritti.')+' Iscritti e inviti vengono conservati. La modifica riguarda solo questa partita, non tutta la serie.</p>');open('groupCreate');}
const groupSubmitBeforeEdit=$('#groupForm').onsubmit;
$('#groupForm').onsubmit=event=>{event.preventDefault();if(!editingGroupId){if(new Date($('#groupDate').value+'T'+$('#groupTime').value).getTime()<=Date.now()){toast('Scegli una data e un orario futuri.');return;}const before=new Set(demoGroups.map(g=>g.id));groupSubmitBeforeEdit(event);for(const g of demoGroups)if(!before.has(g.id))g.ownerId='me';saveGroups();renderGroups();if(activeGroup())renderGroupDetail();return;}const group=demoGroups.find(g=>g.id===editingGroupId);if(!group||!canEditGroup(group)){toast('Puoi modificare solo le tue partite non ancora iniziate.');return;}if(!$('#groupForm').reportValidity())return;const name=$('#groupName').value.trim(),place=$('#groupPlace').value.trim(),capacity=Number($('#groupCapacity').value),date=$('#groupDate').value,time=$('#groupTime').value;if(!name||!place||!Number.isInteger(capacity)||capacity<Math.max(2,group.members.length)||capacity>30){toast('La capienza deve comprendere tutti gli iscritti e non può superare 30.');return;}const others=group.members.some(m=>m.id!=='me');if(others&&(date!==group.date||time!==group.time||place!==group.place)){toast('Data, orario e palestra sono bloccati perché ci sono altri iscritti.');return;}if(new Date(date+'T'+time).getTime()<=Date.now()){toast('Scegli una data e un orario futuri.');return;}Object.assign(group,{name,place,capacity,date,time});saveGroups();resetGroupEditor();renderGroups();renderGroupDetail();open('groupDetail');toast('Partita aggiornata. Iscritti e inviti conservati.');};
const newGroupBeforeEdit=$('#newGroup').onclick;$('#newGroup').onclick=()=>{resetGroupEditor();newGroupBeforeEdit();};
const groupDetailBeforeEdit=renderGroupDetail;renderGroupDetail=function(){groupDetailBeforeEdit();const group=activeGroup();if(!group)return;const duplicate=$('#duplicateGroup');if(duplicate){const duplicateHandler=duplicate.onclick;duplicate.onclick=()=>{resetGroupEditor();duplicateHandler();};}if(canEditGroup(group)){const edit=document.createElement('button');edit.id='editGroup';edit.className='secondary-cta';I18n.text(edit,'Modifica partita');edit.onclick=()=>editGroup(group);$('#findGroupPlayers').after(edit);}else if(group.ownerId==='me')I18n.insert($('#groupDetail'),'beforeend','<p class="groups-note">La partita è iniziata: le modifiche sono bloccate.</p>');};
function syncGroupExploreCards(){document.querySelectorAll('#games [data-organized-group]').forEach(card=>card.remove());for(const group of demoGroups){const card=document.createElement('button');card.className='card game';card.dataset.organizedGroup=group.id;card.dataset.eventDate=group.date;I18n.html(card,'<span class="icon-square">🏐</span><span><strong>'+htmlText(groupDateLabel(group))+'</strong><small data-no-i18n>'+htmlText(group.place)+'</small><span class="group-name" data-no-i18n>'+htmlText(group.name)+'</span></span><span><i class="spots">'+freePlaces(group)+' posti</i><em class="price">Demo</em></span>');card.onclick=()=>{activeGroupId=group.id;renderGroupDetail();open('groupDetail');window.scrollTo(0,0);};$('#games').append(card);}filterExploreGames();}
const groupsBeforeExplore=renderGroups;renderGroups=function(){groupsBeforeExplore();syncGroupExploreCards();};
filterExploreGames=function(){const query=$('#exploreSearch').value.trim().toLocaleLowerCase(),today=localDateKey(new Date()),tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);const nextWeek=new Date();nextWeek.setDate(nextWeek.getDate()+7);let shown=0;document.querySelectorAll('#games .game').forEach(card=>{const date=card.dataset.eventDate||(card.dataset.date==='domani'?localDateKey(tomorrow):today);const dateMatches=activeDateFilter==='settimana'?date>=today&&date<=localDateKey(nextWeek):activeDateFilter==='precisa'?date===$('#exactDate').value:date===(activeDateFilter==='domani'?localDateKey(tomorrow):today);card.hidden=!(dateMatches&&card.textContent.toLocaleLowerCase().includes(query));if(!card.hidden)shown++;});I18n.text($('#viewLabel'),shown?shown+' partite disponibili':'Nessuna partita trovata');};
renderGroups();saveGroups();
